"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[66916],{66916:function(n){n.exports=JSON.parse('{"content":"\\n\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/ccf7bf8c67b43d0aa4a0eb915859de54.jpg\\"\\n  title=\\"청학동칡냉면\\"\\n  cuisine=\\"한식>냉면\\"\\n  address=\\"경기도 화성시 병점구 효행로 466\\"\\n  rating=4.5\\n  tags=\\"restaurant\\"\\n/>\\n</center>\\n\\n## Review\\n<mark>청학동칡냉면</mark>은 소문난 냉면 맛집답게 언제 가도 사람이 많은 곳이다.  \\n그래도 주차장`이 크게 완비되어 있고 식당 내부도 넓은 편이라, 웨이팅이 있어도 회전율이 좋아서 그렇게 오래 기다리지 않고 자리를 안내받을 수 있었다.  \\n\\n식당에 들어가면 먼저 카운터에서 주문하고 `선결제`를 하는 방식이다.  \\n결제가 끝나면 직원분이 자리로 안내해 준다.  \\n```adcard\\n```\\n여기 <mark>다데기</mark>는 매운 편이라, 매운 음식을 잘 못 먹는 사람이라면 비빔냉면은 피하는 게 좋을 것 같다.  \\n아니면 주문할 때 양념을 덜 맵게 해달라고 요청할 수도 있다.  \\n\\n우리는 일반 `물냉면`과 `물냉면 대자`를 하나씩 주문했다.  \\n`대자`라고 해서 양이 확 늘어나는 건 아니고, 면이 조금 더 나오는 수준이었다.  \\n그래도 어차피 먹을 거라면 <mark>대자로 주문하는 것</mark>을 추천하고 싶다.  \\n```adcard\\n```\\n`칡물`과 `온육수`는 셀프로 가져다 먹는 방식이다.  \\n온육수를 한 모금 마셔보면 육수가 꽤 진하다는 걸 바로 느낄 수 있는데, 이 한 잔만으로도 여기가 맛집이라는 게 느껴졌다.  \\n\\n육수를 마시고 잠깐 기다리니 주문한 메뉴가 생각보다 빠르게 나왔다.  \\n회전율이 좋다는 말이 이런 데서도 체감이 됐다.  \\n```adcard\\n```\\n겨자와 식초를 곁들여 먹어도 되지만, 개인적으로는 아무것도 넣지 않고 <mark>순정</mark>으로 먹는것을 추천한다.  \\n그것만으로도 충분히 진한 맛이라 아쉬움이 전혀 없었다.  \\n\\n소문대로, 역시나 맛집이었다.\\n## Pictures\\n\\n<pictures>\\n<img src=\\"/assets/snippets/location/ccf7bf8c67b43d0aa4a0eb915859de54.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"청학동칡냉면\\">\\n<img src=\\"/assets/snippets/location/9de38855f38fcd51067d66d633c0544e.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"청학동칡냉면\\">\\n</pictures>\\n"}')}}]);